#!/usr/bin/env bash
# Freddy Fix It — apply-client-budget-price-grades.sh  (SUPERSET; run ONLY this newest installer)
#   bash ~/freddy-fixit/apply-client-budget-price-grades.sh
#
# What this ships:
#   • Clients can set a budget (min–max, or "I'm flexible — send me quotes").
#   • Everyone sees what that kind of job usually costs in Calgary. Real
#     completed-job averages take over automatically once a category has 5+
#     finished jobs; until then it's the curated price guide, and the UI says
#     which one you're looking at.
#   • Contractors see the client's budget on the job card with an A+/A/A- grade
#     (A+ = pays above market).
#   • Clients see an A+/A/A- price grade on each pro (A+ = better value than
#     market). It needs 3+ jobs or bids before it shows anything.
#
# The DATABASE changes are ALREADY LIVE. This ships the frontend, plus a
# committed copy of the migration so the repo matches the database.
set -e
# Target = the folder this script lives in (your repo), so it works wherever the repo is.
TARGET="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
if [ ! -d "$TARGET/.git" ]; then
  for guess in "$HOME/freddy-fixit" "$HOME/Desktop/freddy-fixit"; do
    if [ -d "$guess/.git" ]; then TARGET="$guess"; break; fi
  done
fi
if [ ! -d "$TARGET/.git" ]; then echo "❌ Couldn't find your freddy-fixit folder. Put this script inside it and run it again."; exit 1; fi
b64dec(){ if base64 --decode >/dev/null 2>&1 <<< "QQ=="; then base64 --decode > "$1"; else base64 -D > "$1"; fi; }
write(){ mkdir -p "$TARGET/$(dirname "$1")"; b64dec "$TARGET/$1"; echo "  ✓ $1"; }
echo "Applying client budget + price grades to $TARGET ..."

# shared pricing + benchmark + grading helpers
